{
  "name": "opencode-terminal-guard",
  "version": "0.1.1",
  "description": "OpenCode TUI compatibility guard that prevents queued mouse reports from leaking into the shell during renderer shutdown.",
  "license": "MIT",
  "author": "Jared Boynton",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/jaredboynton/opencode-terminal-guard.git"
  },
  "homepage": "https://github.com/jaredboynton/opencode-terminal-guard#readme",
  "bugs": {
    "url": "https://github.com/jaredboynton/opencode-terminal-guard/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opentui",
    "terminal",
    "mouse"
  ],
  "type": "module",
  "exports": {
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.js",
      "default": "./dist/tui.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "CHANGELOG.md",
    "LICENSE",
    "package.json"
  ],
  "scripts": {
    "build": "rm -rf dist && tsc -p tsconfig.json",
    "test": "bun test",
    "prepack": "npm run build"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.17.18",
    "@types/node": "^26.1.1",
    "typescript": "^5.9.3"
  },
  "publishConfig": {
    "access": "public"
  }
}
